import{_ as n,C as s,o as l,c as h,j as e,a as o,E as t,a3 as i}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Knives","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/knives.md","filePath":"ru/tools/knives.md"}'),d={name:"ru/tools/knives.md"};function c(u,a,p,g,m,b){const r=s("Screenshot");return l(),h("div",null,[a[0]||(a[0]=e("h1",{id:"knives",tabindex:"-1"},[o("Knives "),e("a",{class:"header-anchor",href:"#knives","aria-label":'Permalink to "Knives"'},"​")],-1)),a[1]||(a[1]=e("p",null,"Knives — сканер движения цен. Он следит за каждым тикером на каждой включённой бирже и показывает карточку в тот момент, когда какой-то из них двигается сильнее заданного вами порога — вверх или вниз.",-1)),a[2]||(a[2]=e("p",null,[o("Все его показатели считаются по "),e("strong",null,"текущей 5-минутной свече"),o(". Тикер появляется потому, что сдвинулась "),e("em",null,"эта"),o(" свеча, а не из-за 24-часовой цифры.")],-1)),t(r,{src:"knives",alt:"Окно Knives с карточками тикеров и мини-графиками",caption:"Окно Knives"}),a[3]||(a[3]=i('<h2 id="как-читать-окно" tabindex="-1">Как читать окно <a class="header-anchor" href="#как-читать-окно" aria-label="Permalink to &quot;Как читать окно&quot;">​</a></h2><h3 id="пока-ничего-не-сработало" tabindex="-1">Пока ничего не сработало <a class="header-anchor" href="#пока-ничего-не-сработало" aria-label="Permalink to &quot;Пока ничего не сработало&quot;">​</a></h3><p>Когда ни один порог ещё не пересечён, окно показывает состояние ожидания вместо карточек:</p><ul><li><strong>Listening</strong> — пульсирующая надпись, а за ней по одной записи на каждую включённую биржу: её иконка, процент срабатывания и порог объёма, если для неё включён фильтр объёма. Это живая сводка того, что Knives сейчас готов поймать.</li><li><strong>No exchanges armed</strong> — все биржи выключены. Сработать не может ничего. Включите хотя бы одну в панели настроек.</li></ul><h3 id="карточка-тикера" tabindex="-1">Карточка тикера <a class="header-anchor" href="#карточка-тикера" aria-label="Permalink to &quot;Карточка тикера&quot;">​</a></h3><p>Каждая карточка состоит из строки-заголовка и мини-графика под ней.</p><p>В заголовке, слева направо:</p><ul><li><strong>Иконки бирж</strong> — на каких биржах торгуется тикер. При наведении показывает <code>Listed on &lt;биржа&gt;</code>. Их можно полностью скрыть — см. <a href="#иконки-бирж">Show icons</a>.</li><li><strong>Значок NEW</strong> — тикер залистили в последние 60 секунд. Значок окрашен в цвет биржи, которая его залистила, а при наведении видно, какой именно. Исчезает, как только тикеру больше минуты.</li><li><strong>Символ тикера</strong> — нажмите, чтобы скопировать его в буфер обмена. На миг появится <code>Copied!</code> для подтверждения.</li></ul><p>Справа:</p><ul><li><strong>Объём</strong> — объём текущей 5м свечи в долларах. Показывается только когда включено отображение объёма — см. <a href="#show-volume-in-tickers">Show volume</a>.</li><li><strong>Изменение цены</strong> — процентное изменение текущей 5м свечи, со знаком.</li><li><strong>Кнопка разворота</strong> — открывает тикер на весь экран.</li></ul><h3 id="что-означают-цвета" tabindex="-1">Что означают цвета <a class="header-anchor" href="#что-означают-цвета" aria-label="Permalink to &quot;Что означают цвета&quot;">​</a></h3><p>Карточка окрашивает свой процент <em>и</em> полоску заголовка в зелёный или красный, как только движение текущей свечи достигает порога <strong>% Change</strong> этой биржи. Ниже порога показатель остаётся нейтральным.</p><p>То есть цвет означает не «цена выросла», а «это движение достигло уровня, о котором вы просили сообщить». Карточка может быть на экране и показывать нейтральный результат, если цена уже откатилась ниже порога.</p><div class="warning custom-block"><p class="custom-block-title">Направление определяется отдельно для каждой биржи</p><p>Для окраски берётся порог той биржи, с которой пришла карточка. Если вы задали разные значения <strong>% Change</strong> для разных бирж, две карточки с одинаковым процентом могут быть окрашены по-разному.</p></div><h3 id="полныи-экран" tabindex="-1">Полный экран <a class="header-anchor" href="#полныи-экран" aria-label="Permalink to &quot;Полный экран&quot;">​</a></h3><p>Кнопка разворота открывает один тикер на всё окно с более крупным графиком и переключателем таймфреймов: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code> и <code>1w</code>.</p><p>В выпадающем списке таймфреймы можно отмечать звёздочкой, чтобы закрепить их строкой быстрого доступа рядом с переключателем. Избранные таймфреймы общие с полноэкранными графиками других инструментов.</p><h3 id="гистограмма-объема" tabindex="-1">Гистограмма объёма <a class="header-anchor" href="#гистограмма-объема" aria-label="Permalink to &quot;Гистограмма объёма&quot;">​</a></h3><p>Кнопка <strong>Vol Ind</strong> в заголовке окна включает или выключает <a href="/manual/ru/customize/chart-colors.html#гистограмма-объема">гистограмму объёма</a> на мини-графиках всех карточек.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>Откройте вкладку <strong>Knives</strong> в главном окне.</p>',21)),t(r,{src:"knives-settings",alt:"Настройки отображения, приоритета данных и иконок бирж в Knives",caption:"Настройки Knives — отображение, приоритет, иконки"}),a[4]||(a[4]=i('<h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-tickers" tabindex="-1">Max tickers <a class="header-anchor" href="#max-tickers" aria-label="Permalink to &quot;Max tickers&quot;">​</a></h4><p>Сколько карточек тикеров окно показывает одновременно. Диапазон <strong>от 3 до 66</strong>, по умолчанию 12.</p><h4 id="show-volume-in-tickers" tabindex="-1">Show volume in tickers <a class="header-anchor" href="#show-volume-in-tickers" aria-label="Permalink to &quot;Show volume in tickers&quot;">​</a></h4><p>Показывает значение объёма в заголовке каждой карточки.</p><p>Этот переключатель <strong>принудительно включён и заблокирован</strong>, когда фильтр объёма включён хотя бы для одной биржи: если вы фильтруете по объёму, Knives всегда показывает объём, по которому фильтровал. Описание при этом меняется на <code>Always on when volume filter is enabled</code>. Чтобы вернуть управление переключателем, выключите фильтр объёма на всех биржах.</p><h3 id="chart-data-priority" tabindex="-1">Chart data priority <a class="header-anchor" href="#chart-data-priority" aria-label="Permalink to &quot;Chart data priority&quot;">​</a></h3><h4 id="exchange-priority" tabindex="-1">Exchange priority <a class="header-anchor" href="#exchange-priority" aria-label="Permalink to &quot;Exchange priority&quot;">​</a></h4><p>Список всех пяти бирж с перетаскиванием. Тяните запись мышью вверх или вниз, чтобы изменить её ранг.</p><p>Это определяет, <strong>какая биржа поставляет свечи для мини-графика</strong>, когда тикер торгуется больше чем на одной. Побеждает первая в списке биржа, которая включена и имеет этот тикер.</p><p>На то, какие биржи могут вызвать оповещение, это не влияет — за это отвечает переключатель <strong>Enable</strong> для каждой биржи ниже.</p><h3 id="иконки-бирж" tabindex="-1">Иконки бирж <a class="header-anchor" href="#иконки-бирж" aria-label="Permalink to &quot;Иконки бирж&quot;">​</a></h3><h4 id="show-icons" tabindex="-1">Show icons <a class="header-anchor" href="#show-icons" aria-label="Permalink to &quot;Show icons&quot;">​</a></h4><p>Показывает или скрывает иконки бирж на всех карточках тикеров. Выключено — карточка плотнее и проще; включено — сразу видно, где торгуется тикер.</p><h3 id="настроики-для-каждои-биржи" tabindex="-1">Настройки для каждой биржи <a class="header-anchor" href="#настроики-для-каждои-биржи" aria-label="Permalink to &quot;Настройки для каждой биржи&quot;">​</a></h3><p>У Knives одинаковый блок настроек для каждой из бирж: <strong>Bybit</strong>, <strong>Binance</strong>, <strong>Gate.io</strong>, <strong>OKX</strong> и <strong>Hyperliquid</strong>. Каждая настраивается независимо — пороги, фильтры объёма и включение отдельные для каждой.</p><h4 id="enable-биржа" tabindex="-1">Enable &lt;биржа&gt; <a class="header-anchor" href="#enable-биржа" aria-label="Permalink to &quot;Enable \\&lt;биржа\\&gt;&quot;">​</a></h4><p>Получает ли Knives оповещения с этой биржи вообще. Выключено — биржа не сканируется, и её тикеры не могут создавать карточки. Все пять по умолчанию включены.</p><p>Выключение биржи делает остальной блок неактивным.</p><h4 id="change" tabindex="-1">% Change <a class="header-anchor" href="#change" aria-label="Permalink to &quot;% Change&quot;">​</a></h4><p>Движение на текущей 5м свече, которое вызывает оповещение для этой биржи. Диапазон <strong>от 2% до 10%</strong> с шагом 0.5%, по умолчанию 2%.</p><p>Это основной порог. Он же определяет, когда показатель карточки становится зелёным или красным.</p><h4 id="high-threshold" tabindex="-1">High threshold <a class="header-anchor" href="#high-threshold" aria-label="Permalink to &quot;High threshold&quot;">​</a></h4><p>Уровень, который считается значительным движением для этой биржи, и точка, на которой срабатывает <a href="#price-change-sound">звук изменения цены</a>. Диапазон <strong>от 2% до 10%</strong> с шагом 0.5%, по умолчанию 6%.</p><div class="warning custom-block"><p class="custom-block-title">Этот ползунок прибавляется к % Change</p><p>Значение рядом с ползунком — это <strong>% Change + High threshold</strong>, а не собственное значение ползунка: при % Change 2% и ползунке на 6% надпись показывает <strong>8.0%</strong>, и именно там срабатывает звук.</p><p>Читайте надпись, а не положение ползунка.</p></div><p>Поскольку значения складываются, повышение <strong>% Change</strong> поднимает и уровень значительного движения. Сначала задайте базовый порог, а затем настраивайте этот поверх него.</p><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фильтрует тикеры этой биржи по объёму торгов, чтобы движения с низкой ликвидностью до вас не доходили. По умолчанию выключено.</p><p>Включение для любой биржи также принудительно включает <a href="#show-volume-in-tickers">Show volume in tickers</a>.</p><h4 id="volume-threshold" tabindex="-1">Volume threshold <a class="header-anchor" href="#volume-threshold" aria-label="Permalink to &quot;Volume threshold&quot;">​</a></h4><p>Минимальный объём в долларах на текущей 5м свече, нужный тикеру, чтобы создать карточку. Диапазон <strong>от $100K до $10M</strong> с шагом $100K, по умолчанию $1M.</p><p>Неактивен, пока для этой биржи не включён фильтр объёма.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="new-ticker-sound" tabindex="-1">New ticker sound <a class="header-anchor" href="#new-ticker-sound" aria-label="Permalink to &quot;New ticker sound&quot;">​</a></h4><p>Воспроизводит звук, когда в окне появляется новый тикер.</p><h4 id="price-change-sound" tabindex="-1">Price change sound <a class="header-anchor" href="#price-change-sound" aria-label="Permalink to &quot;Price change sound&quot;">​</a></h4><p>Воспроизводит звук, когда движение достигает уровня значительного движения для этой биржи — числа, показанного рядом с ползунком <a href="#high-threshold">High threshold</a>.</p><p>Срабатывает не больше одного раза на тикер за свечу, так что тикер, который продолжает двигаться в пределах той же 5м свечи, не будет звенеть многократно.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Оба звука глобальные для Knives, а не отдельные для каждой биржи, независимы друг от друга, и каждый ограничен одним воспроизведением за 2 секунды.</p></div><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/tools/alerts.html">Alerts</a> — расхождения цен между биржами вместо движений на одной</li><li><a href="/manual/ru/tools/monitor.html">Monitor</a> — ранжированный обзор всего рынка вместо ленты срабатываний</li><li><a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a> — цвета свечей, которые используют мини-графики</li><li><a href="/manual/ru/customize/majors.html">Слой мажоров</a> — доступен на полноэкранном графике</li></ul>',41))])}const q=n(d,[["render",c]]);export{f as __pageData,q as default};
